// isISBN — validate ISBN-10 / ISBN-13 (fill-in starter)
// Source: src/lib/isISBN.js (validator.js 13.15.35)
// Contract: options may be { version: 10|13 } or the legacy version argument; without options, try 10 digits first, then 13.
//      Strip spaces and hyphens first; invalid shapes (including X outside the last position) are rejected.

function assertString(input) {
  if (input === undefined || input === null) throw new TypeError(`Expected a string but received a ${input}`);
  if (input.constructor.name !== 'String') throw new TypeError(`Expected a string but received a ${input.constructor.name}`);
}

const possibleIsbn10 = /^(?:[0-9]{9}X|[0-9]{10})$/;
const possibleIsbn13 = /^(?:[0-9]{13})$/;
const factor = [1, 3];

function isISBN(isbn, options) {
  assertString(isbn);

  // For backwards compatibility:
  // isISBN(str [, version]), i.e. `options` could be used as argument for the legacy `version`
  const version = String(options?.version || options);

  if (!(options?.version || options)) {
    return isISBN(isbn, { version: 10 }) || isISBN(isbn, { version: 13 });
  }

  const sanitizedIsbn = isbn.replace(/[\s-]+/g, '');

  let checksum = 0;

  if (version === '10') {
    if (!possibleIsbn10.test(sanitizedIsbn)) {
      return false;
    }

    // TODO: complete the ISBN-10 checksum (mod 11)
    //  - First 9 digits: checksum += (i + 1) * sanitizedIsbn.charAt(i), i from 0 to 8
    //  - Last position: X counts as 10 * 10; a digit counts as 10 * digit
    //  - The decision below is already present: return true when checksum % 11 === 0

    if ((checksum % 11) === 0) {
      return true;
    }
  } else if (version === '13') {
    if (!possibleIsbn13.test(sanitizedIsbn)) {
      return false;
    }

    // TODO: complete the ISBN-13 checksum (1/3 weighting)
    //  - First 12 digits: checksum += factor[i % 2] * sanitizedIsbn.charAt(i), i from 0 to 11
    //  - The decision below is already present: the last digit must equal (10 - checksum % 10) % 10

    if (sanitizedIsbn.charAt(12) - ((10 - (checksum % 10)) % 10) === 0) {
      return true;
    }
  }

  return false;
}

